/**
 * A made-up board that plays a run and a step-through (a small worker pool that
 * leaks one goroutine, and insertion sort on four numbers), for the format,
 * store, server and player tests. Invented content only.
 */
import type { ShapeBoard } from '../../packages/core/shape';
import type { ShapeRun } from '../../packages/core/shape-run';
import type { ShapeSteps } from '../../packages/core/shape-steps';

export const POOL_RUN: ShapeRun = {
  run: 1,
  title: 'Two workers, three jobs: job 2 fails and worker 2 leaks',
  unit: 'ms',
  source: 'scenario, written from pool.go',
  end: 30,
  laneLabel: 'goroutine',
  lanes: [
    { id: 'main', label: 'main' },
    { id: 'w1', label: 'worker 1' },
    { id: 'w2', label: 'worker 2' },
  ],
  resources: { label: 'channel', home: 'own work', items: [{ id: 'jobs', label: 'jobs' }, { id: 'results', label: 'results' }] },
  spans: [
    { lane: 'main', on: 'results', from: 0, to: 12, label: 'range results' },
    { lane: 'w1', from: 0, to: 10, end: 'ok', label: 'job 1' },
    { lane: 'w2', from: 0, to: 14, end: 'error', label: 'job 2' },
    { lane: 'w1', from: 11, to: 20, end: 'ok', label: 'job 3' },
    { lane: 'w2', on: 'results', from: 14, to: 30, end: 'open', label: 'results <- 2' },
  ],
  msgs: [{ from: 'w1', to: 'main', at: 10, arrive: 12, label: 'result 1' }],
  marks: [
    { at: 14, lane: 'w2', label: 'job 2: bad input', tone: 'alert' },
    { at: 16, lane: 'main', label: 'main returns early' },
  ],
  limits: [{ at: 25, label: 'deadline 25 ms', tone: 'alert' }],
};

export const SORT_STEPS: ShapeSteps = {
  steps: 1,
  title: 'Insertion sort on four numbers',
  source: 'generated by running insertion sort on [3, 1, 4, 2]',
  code: { lang: 'go', lines: ['for i := 1; i < len(a); i++ {', '  for j := i; j > 0 && a[j-1] > a[j]; j-- {', '    a[j-1], a[j] = a[j], a[j-1]', '  }', '}'] },
  show: 'array',
  frames: [
    { line: 1, say: 'Start: 3 alone is sorted.', array: [3, 1, 4, 2], cells: { done: [0] }, ptr: { i: 1 } },
    { line: 2, say: '3 > 1, so they swap.', array: [3, 1, 4, 2], cells: { look: [0, 1] }, ptr: { i: 1, j: 1 } },
    { line: 3, say: '1 moves to the front.', array: [1, 3, 4, 2], cells: { moved: [0, 1] }, ptr: { i: 1, j: 0 } },
    { line: 2, say: '3 < 4: 4 stays where it is.', array: [1, 3, 4, 2], cells: { look: [1, 2], done: [0] }, ptr: { i: 2, j: 2 } },
    { line: 3, say: '2 walks left past 4 and 3.', array: [1, 2, 3, 4], cells: { moved: [1, 2, 3] }, ptr: { i: 3, j: 1 } },
    { line: 5, say: 'Done: every number is in its place.', array: [1, 2, 3, 4], cells: { done: [0, 1, 2, 3] }, vars: { swaps: 4 } },
  ],
};

export function runBoard(): ShapeBoard {
  return {
    title: 'The pool leaks a worker when a job fails',
    claim: 'Found. A fix waits on you.',
    views: {
      how: { html: '<h2>One run, played</h2><div data-run="pool"></div><h2>The sort</h2><div data-steps="sort"></div>' },
    },
    runs: { pool: structuredClone(POOL_RUN) },
    steps: { sort: structuredClone(SORT_STEPS) },
  };
}
